import java.util.concurrent.Phaser;

public class PhaserExample {
    public static void main(String[] args) {
        Phaser phaser = new Phaser(1); // Register self (main thread)
        int threadCount = 3;

        for (int i = 1; i <= threadCount; i++) {
            phaser.register();
            new Thread(new Worker(phaser, i)).start();
        }

        // Allow workers to proceed through 2 distinct phases
        for (int phase = 0; phase < 2; phase++) {
            System.out.println("Main thread waiting for phase " + phaser.getPhase() + " to complete.");
            phaser.arriveAndAwaitAdvance();
        }

        phaser.arriveAndDeregister(); // Main thread leaves
        System.out.println("All phases complete. Phaser terminated: " + phaser.isTerminated());
    }

    static class Worker implements Runnable {
        private final Phaser phaser;
        private final int id;

        Worker(Phaser phaser, int id) {
            this.phaser = phaser;
            this.id = id;
        }

        @Override
        public void run() {
            for (int phase = 0; phase < 2; phase++) {
                System.out.println("Worker " + id + " working on phase " + phaser.getPhase());
                phaser.arriveAndAwaitAdvance(); // Sync point
            }
            phaser.arriveAndDeregister();
        }
    }
}
